import { useQuery } from '@tanstack/react-query';
import { dashboardApi } from '../../api/services';
import { StatCard, Spinner } from '../../components/ui';
import {
  Users, Building2, GitBranch, Package, FileText,
  ArrowLeftRight, TrendingUp, UserCheck
} from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend, LineChart, Line, CartesianGrid
} from 'recharts';

const COLORS = ['#6366f1', '#22c55e', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6'];

export default function DashboardPage() {
  const { data: summary, isLoading } = useQuery({
    queryKey: ['dashboard-summary'],
    queryFn: dashboardApi.getSummary,
  });
  const { data: deptData } = useQuery({
    queryKey: ['headcount-dept'],
    queryFn: dashboardApi.headcountByDepartment,
  });
  const { data: trendData } = useQuery({
    queryKey: ['joining-trend'],
    queryFn: dashboardApi.joiningTrend,
  });

  const s = summary?.data?.data || {};
  const deptChart = deptData?.data?.data || [];
  const trend = trendData?.data?.data || [];

  // Fallback mock data for charts when API returns null
  const mockDept = [
    { name: 'Engineering', count: 45 },
    { name: 'HR', count: 12 },
    { name: 'Finance', count: 18 },
    { name: 'Sales', count: 30 },
    { name: 'Operations', count: 22 },
  ];
  const mockTrend = [
    { month: 'Jan', joiners: 5 }, { month: 'Feb', joiners: 8 },
    { month: 'Mar', joiners: 12 }, { month: 'Apr', joiners: 7 },
    { month: 'May', joiners: 15 }, { month: 'Jun', joiners: 10 },
  ];

  const chartDept = deptChart.length ? deptChart : mockDept;
  const chartTrend = trend.length ? trend : mockTrend;

  if (isLoading) {
    return <div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>;
  }

  return (
    <div className="space-y-6">
      {/* Stat Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
        <StatCard title="Total Employees" value={s.totalEmployees ?? 0} icon={Users} color="indigo" />
        <StatCard title="Active Employees" value={s.activeEmployees ?? 0} icon={UserCheck} color="green" />
        <StatCard title="On Probation" value={s.onProbation ?? 0} icon={Users} color="yellow" />
        <StatCard title="Departments" value={s.totalDepartments ?? 0} icon={Building2} color="blue" />
        <StatCard title="Branches" value={s.totalBranches ?? 0} icon={GitBranch} color="indigo" />
        <StatCard title="Total Assets" value={s.totalAssets ?? 0} icon={Package} color="orange" />
        <StatCard title="Pending Transfers" value={s.pendingTransfers ?? 0} icon={ArrowLeftRight} color="red" />
        <StatCard title="Docs Expiring (30d)" value={s.docsExpiringSoon ?? 0} icon={FileText} color="red" subtitle="Needs attention" />
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Headcount by Department */}
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <h3 className="text-sm font-semibold text-slate-700 mb-4">Headcount by Department</h3>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={chartDept} margin={{ top: 0, right: 10, left: -20, bottom: 0 }}>
              <XAxis dataKey="name" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip />
              <Bar dataKey="count" fill="#6366f1" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Joining Trend */}
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <h3 className="text-sm font-semibold text-slate-700 mb-4">Monthly Joining Trend</h3>
          <ResponsiveContainer width="100%" height={220}>
            <LineChart data={chartTrend} margin={{ top: 0, right: 10, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
              <XAxis dataKey="month" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip />
              <Line type="monotone" dataKey="joiners" stroke="#6366f1" strokeWidth={2} dot={{ r: 4 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Pie Chart */}
      <div className="bg-white rounded-xl border border-slate-200 p-5 max-w-md">
        <h3 className="text-sm font-semibold text-slate-700 mb-4">Department Distribution</h3>
        <ResponsiveContainer width="100%" height={220}>
          <PieChart>
            <Pie data={chartDept} dataKey="count" nameKey="name" cx="50%" cy="50%" outerRadius={80} label>
              {chartDept.map((_, i) => (
                <Cell key={i} fill={COLORS[i % COLORS.length]} />
              ))}
            </Pie>
            <Legend />
            <Tooltip />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
